ac1.command:
set -u
command -v python3 >/dev/null 2>&1 || { echo "ac1 RED: python3 missing - the policy contract cannot be parsed"; exit 1; }
python3 - <<'PYEOF' || exit 1
import re, sys
try:
    import yaml
except Exception as exc:
    print("ac1 RED: PyYAML not importable (%s) - the policy fence pins python3+PyYAML, no fallback" % exc)
    sys.exit(1)
POL = "incident-response/autonomy-policy.yaml"
try:
    doc = yaml.safe_load(open(POL, encoding="utf-8").read())
except Exception as exc:
    print("ac1 RED: %s missing or unparseable (%s)" % (POL, exc))
    sys.exit(1)
COMPOSE = re.compile(r"^docker compose(\s|$)")
OUTSIDE = re.compile(r"kubectl|systemctl|service\s|docker restart|git\s", re.I)

def third_class_legs(document):
    """The decisive assertions of this AC; returns a list of defects (empty = pass)."""
    fail = []
    allowed = document.get("allowed_actions") or []
    denied = document.get("denied_actions") or []
    denied_ids = {str(e.get("id")) for e in denied if isinstance(e, dict)}
    if str(document.get("default_decision")) != "deny":
        fail.append("default_decision is no longer deny - the deny floor is this card's premise, not its bargaining chip")
    if str(document.get("unknown_action_decision")) != "deny":
        fail.append("unknown_action_decision is no longer deny")
    trio = {"restart_production", "database_mutation", "merge"}
    if not trio <= denied_ids:
        fail.append("the denied trio drifted: have %s, need restart_production + database_mutation + merge" % sorted(denied_ids))
    rem = [e for e in allowed if isinstance(e, dict) and str(e.get("class")) == "safe_local_remediation"]
    if len(rem) < 1:
        fail.append("no allowed_actions entry carries class safe_local_remediation - the third scoped class is the whole product of this card (RED at base by design)")
    ids = set()
    for e in rem:
        ident = str(e.get("id") or "?")
        ids.add(ident)
        if str(e.get("environment") or "").strip() != "local-compose-only":
            fail.append("remediation allow %s lacks the scope guard environment: local-compose-only - an unscoped third class is exactly the gap the t82 fence refused" % ident)
        cmds = e.get("commands") or []
        if not cmds:
            fail.append("remediation allow %s names no command shape" % ident)
        for c in cmds:
            if not COMPOSE.match(str(c)) or OUTSIDE.search(str(c)):
                fail.append("remediation command %r escapes the local compose grammar (docker compose ... only; kubectl/systemctl/service/docker restart/git stay denied)" % str(c))
        if "local" not in str(e.get("scope") or "").lower():
            fail.append("remediation allow %s scope sentence never says local - the boundary of the class is the word" % ident)
    if ids & denied_ids:
        fail.append("action id(s) appear in BOTH allowed_actions and denied_actions: %s" % sorted(ids & denied_ids))
    return fail

live_fail = third_class_legs(doc)
# NEGATIVE CONTROL: the OLD two-class state must be REJECTED by these same legs.
import copy
old_state = copy.deepcopy(doc)
old_state["allowed_actions"] = [e for e in (old_state.get("allowed_actions") or [])
                                if isinstance(e, dict) and str(e.get("class")) != "safe_local_remediation"]
if not third_class_legs(old_state):
    print("ac1 RED: NEGATIVE CONTROL FAILED - the two-class state passed the third-class legs, so the legs are vacuous")
    sys.exit(1)
if live_fail:
    sys.stdout.write("ac1 evidence: " + "; ".join(live_fail) + "\n")
    print("ac1 RED: the third-class policy contract is not satisfied (%d defects)" % len(live_fail))
    sys.exit(1)
rem = [e for e in doc["allowed_actions"] if isinstance(e, dict) and str(e.get("class")) == "safe_local_remediation"]
sys.stdout.write("ac1 evidence: %d safe_local_remediation entries, every one guarded by environment: local-compose-only, every command inside the docker compose grammar, default_decision=deny intact, denied trio %s intact, no id in both lists; the same legs REJECT the two-class state (negative control armed)\n"
                 % (len(rem), sorted({"restart_production", "database_mutation", "merge"})))
PYEOF
echo "ac1 GREEN: the third action class exists, is local-compose-only scoped, and did not move the deny floor or the denied trio"

ac3.command:
set -u
T=incident-response/responder-task.md
S=incident-response/response.schema.json
test -f "$T" || { echo "ac3 RED: $T missing"; exit 1; }
test -f "$S" || { echo "ac3 RED: $S missing"; exit 1; }
SH() { tr -d "\r" < "$T"; }
SH | grep -qF "You diagnose; a human operates" || { echo "ac3 RED: the boundary sentence 'You diagnose; a human operates' is GONE - t123 widens the policy allow-list, it does not move the prompt boundary; the sentence must survive verbatim"; exit 1; }
SH | grep -qF "READ-ONLY" || { echo "ac3 RED: the prompt no longer states READ-ONLY - the six read-only answer actions are unchanged by this card"; exit 1; }
SH | grep -qiF "incident-response/autonomy-policy.yaml" || { echo "ac3 RED: the prompt no longer cites the policy as the boundary authority"; exit 1; }
for a in read_health read_metrics read_logs read_version read_manifest write_report; do
  SH | grep -qF "$a" || { echo "ac3 RED: the prompt no longer names the read-only action $a - the six-action answer contract is unchanged by t123"; exit 1; }
  grep -qF "$a" "$S" || { echo "ac3 RED: $S no longer names $a - the schema is FROZEN for this card (remediation recordability is t124 scope)"; exit 1; }
done
python3 - "$S" <<'PYEOF' || exit 1
import hashlib, json, sys
b = open(sys.argv[1], "rb").read().replace(b"\r\n", b"\n")
got = hashlib.sha256(b).hexdigest()
want = "bc98b1c9d6653dbf6093f4f3bf98498dcc01cfd8cbf35225c698bbdc85e4a841"
if got != want:
    print("ac3 RED: response.schema.json moved (CR-stripped sha %s, pinned %s) - this card writes ZERO bytes to the schema; the six read-only enum is t124's to extend" % (got[:12], want[:12]))
    sys.exit(1)
doc = json.load(open(sys.argv[1], encoding="utf-8"))
enum = doc["properties"]["actions_taken"]["items"]["properties"]["action"]["enum"]
if sorted(enum) != sorted(["read_health", "read_metrics", "read_logs", "read_version", "read_manifest", "write_report"]):
    print("ac3 RED: the actions_taken enum is %s - the six read-only names are the frozen recordable set" % enum)
    sys.exit(1)
sys.stdout.write("ac3 evidence: response.schema.json byte-frozen at the pinned CR-stripped digest; actions_taken admits exactly the six read-only names - remediation actions are NOT recordable in an incident answer until t124 extends the enum (disclosed, not worked around)\n")
PYEOF
BAD=$(SH | grep -iE "restart_local_observability|clear_local_caches|re_run_local_validators|safe_local_remediation" | grep -viE "never|must not|forbidden|denied|not recordable|out of scope|t124" | grep -c . || true)
[ "${BAD:-0}" = 0 ] || { echo "ac3 RED: the prompt names a remediation action on a line with no prohibition or t124-scope word (${BAD} line(s)) - the responder stays READ-ONLY while the policy grows a local class"; exit 1; }
for w in ".env" "~/.ssh" printenv; do
  SH | grep -qF -- "$w" || { echo "ac3 RED: the prompt no longer names $w in its prohibition - the forbidden-actions table must be stated to the responder, not assumed"; exit 1; }
done
NOSTOP=$(SH | grep -E "[.]env|ssh|printenv" | grep -viE "never|must not|forbidden|secret-free|no secret" | grep -c . || true)
[ "${NOSTOP:-0}" = 0 ] || { echo "ac3 RED: a secret-path line in the prompt carries no prohibition word - a bare mention of .env or ~/.ssh reads as an instruction"; exit 1; }
CTRL=$(SH | sed "s/[Nn]ever/MAY/g" | grep -E "[.]env|ssh|printenv" | grep -viE "never|must not|forbidden" | grep -c . || true)
[ "${CTRL:-0}" -ge 1 ] || { echo "ac3 RED: NEGATIVE CONTROL FAILED - rewriting Never to MAY left no secret-path line unprohibited, so the prohibition legs above were vacuous"; exit 1; }
echo "ac3 evidence: NEGATIVE CONTROL - the Never-to-MAY rewrite finds $CTRL unprohibited secret-path line(s), so the READ-ONLY prohibition legs bite"
echo "ac3 GREEN: the boundary is verbatim, the six read-only actions are named in prompt and schema, the schema is byte-frozen, and no remediation action leaks into the responder contract"

ac4.command:
set -u
command -v python3 >/dev/null 2>&1 || { echo "ac4 RED: python3 missing"; exit 1; }
A=docs/state/outputs/t123_definer_gate_amendment.json
T121=docs/state/outputs/t121_definer_gate_amendment.json
test -f "$A" || { echo "ac4 RED: $A missing - the W2 proposal is the written record the orchestrator applies in the merge window"; exit 1; }
test -f "$T121" || { echo "ac4 RED: $T121 missing - its STALE base must be disclosed, not silently cited"; exit 1; }
python3 - "$A" "$T121" <<'PYEOF' || exit 1
import base64, hashlib, json, re, sys
rec = json.load(open(sys.argv[1], encoding="utf-8"))
t121 = json.load(open(sys.argv[2], encoding="utf-8"))
raw = open("docs/state/merge_test_index.json", "rb").read()
live_sha = hashlib.sha256(raw).hexdigest()
tests = json.loads(raw.decode("utf-8"))["tests"]
fail = []
if rec.get("status") != "proposed":
    fail.append("amendment status is %r - the definer proposes, the orchestrator applies" % rec.get("status"))
if rec.get("policy") != "W2" or rec.get("card_writes_index_bytes") is not False \
        or rec.get("no_leg_deleted") is not True or rec.get("verifier_thresholds_touched") is not False:
    fail.append("the W2 eight-property envelope fields are not intact")
if [a["index"] for a in rec["amendments"]] != [288]:
    fail.append("the amendment set is %s - the sweep found exactly one stale leg premise (leg 288)" % [a["index"] for a in rec["amendments"]])
am = rec["amendments"][0]
cmd = tests[288]["command"]
def csha(s): return hashlib.sha256(s.encode()).hexdigest()
def esha(x): return hashlib.sha256(json.dumps(x, separators=(",", ":")).encode()).hexdigest()
live_is_old = (csha(cmd) == am["old_command_sha256"] and len(cmd) == am["old_command_len"]
               and esha(tests[288]) == am["entry_sha_before"])
live_is_new = csha(cmd) == am["new_command_sha256"] and esha(tests[288]) == am["entry_sha_after"]
if not (live_is_old or live_is_new):
    fail.append("leg 288 matches neither the old nor the amended pins - the index moved off both bases; re-pin before applying")
for r in am["replaced_regions"]:
    if live_is_old and cmd.count(r["from"]) != 1:
        fail.append("region from-string not unique in the live command: %r" % r["from"][:60])
# SWEEP: exactly one leg carries the two-class absence premise (command text or base64 payload).
def payloads(c):
    out = [c]
    for m in re.finditer(r"B64=([A-Za-z0-9+/=]{40,})", c):
        try:
            out.append(base64.b64decode(m.group(1)).decode("utf-8", "ignore"))
        except Exception:
            pass
    return out
stale = []
for i, t in enumerate(tests):
    texts = payloads(t["command"])
    if any(('{"read_only_reads", "report_writing"}' in x or "no third action class admitted" in x) for x in texts):
        stale.append(i)
if stale != [288]:
    fail.append("the two-class absence premise was found on legs %s - the amendment set must cover every stale premise, and the sweep must name exactly one victim" % stale)
# The t121 amendment is STALE against the live index and must stay disclosed.
t121_base = t121["base"]["index_file_sha256"]
if t121_base == live_sha:
    fail.append("t121's base equals the live index - the stale-base disclosure this card carries would be false")
if "e98f96bd" not in json.dumps(rec):
    fail.append("the t123 record does not name t121's stale base e98f96bd - a stale pin cited without disclosure is how silent-fence bugs happen")
if fail:
    sys.stdout.write("ac4 evidence: " + "; ".join(fail) + "\n")
    print("ac4 RED: the carrier disposition is not sound (%d defects)" % len(fail))
    sys.exit(1)
sys.stdout.write("ac4 evidence: live index %s; leg 288 pins verify (%s); the sweep over all %d legs (base64 payloads decoded) names EXACTLY leg 288 as carrying the two-class premise; carrier legs 283/284/285/286/287/302-306 stay untouched and GREEN; legs 289/290 are environmental CR-smudge REDs disclosed not healed; t121's amendment base %s is stale vs live %s and is disclosed, never silently cited\n"
                 % (live_sha[:8], "old pins" if live_is_old else "amended pins", len(tests), t121_base[:8], live_sha[:8]))
PYEOF
echo "ac4 GREEN: one stale leg, one proposed W2 amendment, the sweep proves the set is complete, and every disclosed defect stays disclosed"

ac5.command:
set -u
command -v python3 >/dev/null 2>&1 || { echo "ac5 RED: python3 missing"; exit 1; }
TM=docs/criteria/scoring_map/telemetry.md
RD=README.md
test -f "$TM" || { echo "ac5 RED: $TM missing"; exit 1; }
test -f "$RD" || { echo "ac5 RED: $RD missing"; exit 1; }
python3 - "$TM" "$RD" <<'PYEOF' || exit 1
import glob, os, re, sys
tm = open(sys.argv[1], encoding="utf-8", errors="replace").read().replace("\r\n", "\n")
rd = open(sys.argv[2], encoding="utf-8", errors="replace").read().replace("\r\n", "\n")
fail = []
m = re.search(r"^## On-Call Agent\n(.*?)(?=^## |\Z)", tm, re.S | re.M)
if not m:
    fail.append("telemetry.md has no '## On-Call Agent' section")
else:
    sec = m.group(1)
    if "- Claim: 1/2" not in sec:
        fail.append("the On-Call claim is not the pinned '1/2' - t123 is the POLICY half only; 2/2 requires t124's measured drill (a measured agent fix), and raising the claim without it is the honesty failure this fence exists to catch")
    if "- Gap:" not in sec:
        fail.append("the On-Call Gap line is gone - the gap sentence is the honest half of the 1/2 claim")
lines = rd.split("\n")
if len(lines) < 286 or "| 12 | On-Call Agent (0-2) | 1/2 |" not in lines[285]:
    fail.append("README row 12 (line 286) is not '| 12 | On-Call Agent (0-2) | 1/2 | ...' - the table row and the telemetry section must agree at 1/2")
if "| 12 | On-Call Agent (0-2) | 2/2 |" in rd:
    fail.append("README already claims On-Call 2/2 - that claim belongs to t124 with drill evidence, not to this card")
# honesty leg: telemetry.md has NO generator. The section is hand-authored; the
# "run the generator" premise is FALSE and must stay disclosed. Negative
# control: the same sweep armed on a self-chosen pattern finds this very card.
gen = []
for p in ("backend/scripts", "scripts", "ops", "dev"):
    for root, _dirs, files in os.walk(p):
        for f in files:
            fp = os.path.join(root, f)
            try:
                src = open(fp, encoding="utf-8", errors="ignore").read()
            except Exception:
                continue
            if "scoring_map/telemetry" in src:
                gen.append(fp)
if gen:
    fail.append("a scoring_map/telemetry writer was found at %s - the pinned-section premise of this AC would be false; re-groom (this card pinned a MEASURED section, not generated output)" % gen)
self_hit = 0
for fp in glob.glob("docs/issues/t123.md"):
    if "scoring_map/telemetry" in open(fp, encoding="utf-8", errors="ignore").read():
        self_hit += 1
if self_hit == 0:
    fail.append("NEGATIVE CONTROL FAILED - the generator sweep found nothing AND cannot even see its own card, so the sweep is vacuous")
if fail:
    sys.stdout.write("ac5 evidence: " + "; ".join(fail) + "\n")
    print("ac5 RED: the On-Call claim is not a sound pinned 1/2 (%d defects)" % len(fail))
    sys.exit(1)
sys.stdout.write("ac5 evidence: On-Call pinned at Claim 1/2 in telemetry.md (lines 38-45) with the Gap line intact; README row 12 line 286 agrees; the sweep of backend/scripts, scripts, ops and dev finds NO telemetry.md generator (the section is hand-authored - the 'run the generator' premise is disclosed FALSE); the sweep is armed (it sees this card)\n")
PYEOF
echo "ac5 GREEN: the On-Call claim stays a measured 1/2 (policy half here, drill half t124), pinned in both carriers, with the no-generator honesty sentence on the record"

ac6.command:
set -u
command -v python3 >/dev/null 2>&1 || { echo "ac6 RED: python3 missing"; exit 1; }
A=docs/state/outputs/t123_definer_gate_amendment.json
test -f "$A" || { echo "ac6 RED: $A missing - the region proofs are what the orchestrator applies; they must reconstruct against the live index"; exit 1; }
python3 - "$A" <<'PYEOF' || exit 1
import copy, hashlib, json, sys
rec = json.load(open(sys.argv[1], encoding="utf-8"))
raw = open("docs/state/merge_test_index.json", "rb").read()
tests = json.loads(raw.decode("utf-8"))["tests"]
def csha(s): return hashlib.sha256(s.encode()).hexdigest()
def esha(x): return hashlib.sha256(json.dumps(x, separators=(",", ":")).encode()).hexdigest()
fail = []
if rec.get("status") != "proposed":
    fail.append("amendment status is %r, not 'proposed' - the definer proposes, the orchestrator applies" % rec.get("status"))
if rec.get("card_writes_index_bytes") is not False:
    fail.append("card_writes_index_bytes must be False")
if rec.get("policy") != "W2":
    fail.append("policy must be W2")
want = {288}
have = {a["index"] for a in rec["amendments"]}
if have != want:
    fail.append("amendment index set is %s, expected %s (leg 288 only - the sweep found exactly one stale premise)" % (sorted(have), sorted(want)))
for a in rec["amendments"]:
    i = a["index"]
    cmd = tests[i]["command"]
    built = cmd
    for reg in a["replaced_regions"]:
        n = cmd.count(reg["from"])
        if n != 1:
            fail.append("leg %d: region from-string occurs %d times (must be exactly 1): %r" % (i, n, reg["from"][:60]))
        built = built.replace(reg["from"], reg["to"], 1)
    back = built
    for reg in reversed(a["replaced_regions"]):
        back = back.replace(reg["to"], reg["from"], 1)
    if back != cmd:
        fail.append("leg %d: region replacement is not reverse-lossless" % i)
    if built == cmd:
        fail.append("leg %d: the amendment is a no-op dressed as a fix" % i)
    if csha(cmd) == a["old_command_sha256"]:
        if len(cmd) != a["old_command_len"]:
            fail.append("leg %d: old_command_len does not match the live entry" % i)
        if esha(tests[i]) != a["entry_sha_before"]:
            fail.append("leg %d: entry_sha_before does not match the live entry" % i)
        if csha(built) != a["new_command_sha256"] or len(built) != a["new_command_len"]:
            fail.append("leg %d: new_command_sha256/len do not reconstruct from the regions" % i)
        e2 = copy.deepcopy(tests[i]); e2["command"] = built
        if esha(e2) != a["entry_sha_after"]:
            fail.append("leg %d: entry_sha_after does not reconstruct from the built entry" % i)
    elif csha(cmd) == a["new_command_sha256"]:
        if esha(tests[i]) != a["entry_sha_after"]:
            fail.append("leg %d: amended entry_sha_after does not match the applied live entry" % i)
        if csha(back) != a["old_command_sha256"]:
            fail.append("leg %d: reverse reconstruction of the OLD command failed after apply" % i)
    else:
        fail.append("leg %d: the live entry matches neither the old nor the amended pins - the index moved off both bases" % i)
if "e98f96bd" not in json.dumps(rec):
    fail.append("the record does not disclose t121's stale base e98f96bd")
if "289" not in json.dumps(rec) or "autocrlf" not in json.dumps(rec).lower():
    fail.append("the record does not disclose the environmental 289/290 CR-smudge REDs")
sys.stdout.write("ac6 evidence: the leg-288 amendment reconstructs against the live index (uniqueness, forward build, LIFO reverse-lossless, entry shas); status proposed; zero index bytes written by this card; the stale t121 base and the environmental 289/290 REDs are disclosed in the record itself\n")
PYEOF
if git rev-parse --git-dir >/dev/null 2>&1; then
  BASE=$(git merge-base HEAD origin/main 2>/dev/null || true)
  if [ -n "${BASE:-}" ]; then
    OUT=$(git diff --name-only "$BASE"...HEAD \
      | grep -vE '^(incident-response/autonomy-policy\.yaml|incident-response/responder-task\.md|incident-response/response\.schema\.json|docs/criteria/scoring_map/telemetry\.md|README\.md|docs/issues/t123\.md|docs/state/outputs/t123_)' || true)
    [ -z "$OUT" ] || { echo "ac6 RED: the branch moved paths outside the owned surfaces (a .sh byte in this list would be the environmental CR-smudge 'fix' this card forbids): $OUT"; exit 1; }
    echo "ac6 evidence: builder delta is inside the owned product paths only (policy yaml, responder prompt, frozen schema, telemetry.md, README, this card, the two t123 outputs) and zero .sh bytes"
  fi
fi
echo "ac6 GREEN: the amendment is sound against the live index, the delta is pure, no .sh byte moves, and every disclosed defect stays disclosed"
